const FIXED_CASES_SHA = '20cc029ffd956db0aa94882fab740e0270f3a5b90eab42707f1ae1ebcdcdf1f3'
test('exact deeper continuation matrix and seeded mixed byte stream fit declared bounds',()=>{
  assert.equal(cases.length,400);assert.equal(new Set(cases.map(c=>c.name)).size,400)
  assert.equal(createHash('sha256').update(JSON.stringify(cases)).digest('hex'),FIXED_CASES_SHA)
  assert.equal(cases.filter(c=>c.category==='third').length,72)
  assert.equal(cases.filter(c=>c.category==='fourth').length,288)
  assert.equal(cases.filter(c=>c.category==='mixed').length,40)
  assert.equal(Math.max(...cases.map(c=>c.values[1].length/2)),32)
  for(const c of cases) {
    assert.deepEqual(rowsFor(c),[{id:1,valueHex:null},{id:2,valueHex:c.anchorHex+'42'}])
    assert.equal(c.sourceWidth,64);assert.equal(c.wireWidth,64);assert.equal(c.targetWidth,64)
    assert.equal(c.declared,'utf8');assert.equal(c.wire,'utf8');assert.equal(c.target,'utf8')
  }
  assert.throws(()=>rowsFor({...cases[0],values:[null,'00'.repeat(33)]}))
  assert.throws(()=>rowsFor({...cases[0],values:[null,'x']}))
})
test('four original runs preserve every raw native/unit/display/diagnostic outcome separately',async()=>{
  const bytes=await readFile(fixture),f=JSON.parse(bytes);validateRetained(bytes);validate(f)
  assert.equal(observed.length,400)
  for(const run of f.runs)for(const [i,o]of run.observations.entries()) {
    const oracle=observed[i];assert.equal(o.case.name,oracle.name)
    assert.deepEqual(o.execution.result,oracle.execution,o.case.name)
    assert.deepEqual(o.readback.result,oracle.readback,o.case.name)
    assert.deepEqual(o.recoveryReadback?.result??null,oracle.recovery,o.case.name)
    assert.equal(o.readback.session,'original')
  }
  const replay=spawnSync(process.execPath,['scripts/capture-bulk-character-utf8-multibyte.mjs','--replay-fixture'],{cwd:new URL('../',import.meta.url),encoding:'utf8',env:{...process.env,PATH:''},timeout:15000})
  assert.equal(replay.status,0,replay.stderr)
})
test('uniform units/native/counters/type/source corruption and omissions fail independent pins',async()=>{
  const retained=await load(),name='utf8-multibyte-third-efa080'
  for(const mutate of [
    o=>{o.execution.result.rowCount=99},o=>{o.case.sourceWidth='max'},
    o=>{o.readback.result.sets[1].rows[1][4].value='fdff4200'},
    o=>{o.readback.result.sets[1].rows[1][2].value='efbfbdefbfbd42'},
    o=>{o.readback.result.sets[0].rows[0][0]=9833},
    o=>{o.metadata.result.sets[0].columns[0].length=65535},o=>{o.case.anchorHex='42'}
  ]) {
    const f=structuredClone(retained);for(const run of f.runs)mutate(find(run,name))
    f.comparisons=f.runs.slice(1).map(r=>compare(r,f.runs[0]));assert.throws(()=>validate(f),/fixed/)
  }
  const omitted=structuredClone(retained);for(const run of omitted.runs)run.observations.pop()
  omitted.comparisons=omitted.runs.slice(1).map(r=>compare(r,omitted.runs[0]));assert.throws(()=>validate(omitted))
  for(const field of ['sourceSha','helperSha','nodeVersion']) {const f=structuredClone(retained);f.provenance[field]='0'.repeat(64);assert.throws(()=>validate(f),/fixed/)}
  const f=structuredClone(retained);f.provenance.helpers['capture-bulk-character-utf8-octet.mjs']='0'.repeat(64);assert.throws(()=>validate(f),/fixed/)
})
